"        <input id=\"m2\" type=\"text\" value=\"a scribe for a king\" style=\"height: 44px; box-sizing: border-box; padding: 0 12px; border: 1px solid #C9BCA4; border-radius: 8px; background: #FFFFFF; font-size: 15px; color: #1E1A15;\">\n      </div>\n      <div style=\"display: flex; flex-direction: column; gap: 4px;\">\n        <label for=\"m3\" style=\"font-size: 13px; font-weight: 600;\">3 · What was it for?</label>\n        <input id=\"m3\" type=\"text\" placeholder=\"Your reading\" style=\"height: 44px; box-sizing: border-box; padding: 0 12px; border: 1px solid #C9BCA4; border-radius: 8px; background: #FFFFFF; font-size: 15px; color: #1E1A15;\">\n      </div>\n    </div>\n\n    <button type=\"button\" style=\"height: 48px; border: 0; border-radius: 10px; background: #A0431F; color: #FFFFFF; font-size: 15px; font-weight: 500;\">Reveal the record</button>\n    <span style=\"font-size: 12px; color: #6B6154; text-align: center;\">The rest of this unit waits for your desk session.</span>\n  </main>\n\n  <nav aria-label=\"Sections\" style=\"height: 64px; box-sizing: border-box; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid #DCD3C4; background: #FBF8F2;\">\n",
